// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetApplication 查询应用
	// (GET /api/v1/applications/{applicationId})
	GetApplication(ctx context.Context, request GetApplicationRequestObject) (GetApplicationResponseObject, error)
	// CreateDeploymentTarget 创建部署目标
	// (POST /api/v1/applications/{applicationId}/deployment-targets)
	CreateDeploymentTarget(ctx context.Context, request CreateDeploymentTargetRequestObject) (CreateDeploymentTargetResponseObject, error)
	// GetDeploymentTarget 查询部署目标
	// (GET /api/v1/deployment-targets/{deploymentTargetId})
	GetDeploymentTarget(ctx context.Context, request GetDeploymentTargetRequestObject) (GetDeploymentTargetResponseObject, error)
	// UpdateDeploymentTarget 更新部署目标的可变期望配置
	// (PUT /api/v1/deployment-targets/{deploymentTargetId})
	UpdateDeploymentTarget(ctx context.Context, request UpdateDeploymentTargetRequestObject) (UpdateDeploymentTargetResponseObject, error)
	// CreateRelease 创建发布并接纳异步操作
	// (POST /api/v1/deployment-targets/{deploymentTargetId}/releases)
	CreateRelease(ctx context.Context, request CreateReleaseRequestObject) (CreateReleaseResponseObject, error)
	// GetRuntimeSnapshot 从 Kubernetes 查询部署目标的当前运行状态
	// (GET /api/v1/deployment-targets/{deploymentTargetId}/runtime-snapshot)
	GetRuntimeSnapshot(ctx context.Context, request GetRuntimeSnapshotRequestObject) (GetRuntimeSnapshotResponseObject, error)
	// GetOperation 查询异步操作
	// (GET /api/v1/operations/{operationId})
	GetOperation(ctx context.Context, request GetOperationRequestObject) (GetOperationResponseObject, error)
	// CreateProject 创建项目
	// (POST /api/v1/projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// GetProject 查询项目
	// (GET /api/v1/projects/{projectId})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// CreateApplication 创建应用
	// (POST /api/v1/projects/{projectId}/applications)
	CreateApplication(ctx context.Context, request CreateApplicationRequestObject) (CreateApplicationResponseObject, error)
	// ListProjectMembers 查询项目成员
	// (GET /api/v1/projects/{projectId}/members)
	ListProjectMembers(ctx context.Context, request ListProjectMembersRequestObject) (ListProjectMembersResponseObject, error)
	// AddProjectMember 添加项目成员
	// (POST /api/v1/projects/{projectId}/members)
	AddProjectMember(ctx context.Context, request AddProjectMemberRequestObject) (AddProjectMemberResponseObject, error)
	// RemoveProjectMember 移除项目成员
	// (DELETE /api/v1/projects/{projectId}/members/{actorId})
	RemoveProjectMember(ctx context.Context, request RemoveProjectMemberRequestObject) (RemoveProjectMemberResponseObject, error)
	// UpdateProjectMember 修改项目成员角色
	// (PUT /api/v1/projects/{projectId}/members/{actorId})
	UpdateProjectMember(ctx context.Context, request UpdateProjectMemberRequestObject) (UpdateProjectMemberResponseObject, error)
	// GetRelease 查询发布
	// (GET /api/v1/releases/{releaseId})
	GetRelease(ctx context.Context, request GetReleaseRequestObject) (GetReleaseResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

